//! An SSH bastion container for integration tests, on a Docker network with servers that
//! are not published to the host: the only way to them is through the bastion.
//!
//! The bastion is `linuxserver/openssh-server` (pinned in [`SSHD_IMAGE`]) with TCP
//! forwarding turned on through a drop-in in `/config/sshd/sshd_config.d`, one user
//! ([`SSH_USER`]) and one authorized ed25519 key generated by the test. Only its SSH port
//! is published. Its host key is read from the container, never trusted on first use.

use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::time::{Duration, Instant};

use redis_lens::model::{Endpoint, SshTunnel};
use testcontainers::core::{CmdWaitFor, ExecCommand, IntoContainerPort, WaitFor};
use testcontainers::runners::AsyncRunner;
use testcontainers::{ContainerAsync, CopyTargetOptions, GenericImage, ImageExt};

/// The sshd image, pinned. CI pulls it in its image step.
pub const SSHD_IMAGE: (&str, &str) = ("linuxserver/openssh-server", "10.3_p1-r2-ls243");
/// The bastion's login. Distinctive, so tests can check it appears nowhere it shouldn't.
pub const SSH_USER: &str = "lens-tunnel-u8k2q";
const SSH_PORT: u16 = 2222;
const HOST_KEY: &str = "/config/ssh_host_keys/ssh_host_ed25519_key.pub";

static SEQ: AtomicUsize = AtomicUsize::new(0);

/// A name unique to this test run: for networks, containers and temp dirs.
pub fn unique(tag: &str) -> String {
    format!(
        "redis-lens-ssh-{tag}-{}-{}-{}",
        std::process::id(),
        SEQ.fetch_add(1, Ordering::SeqCst),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .subsec_nanos()
    )
}

/// A fresh directory under the target's temp dir.
pub fn temp_dir(tag: &str) -> PathBuf {
    let dir = Path::new(env!("CARGO_TARGET_TMPDIR")).join(unique(tag));
    std::fs::create_dir_all(&dir).expect("create a temp dir");
    dir
}

/// An ed25519 key pair made with `ssh-keygen -N ''`.
pub struct Key {
    pub private: PathBuf,
    /// The `.pub` line.
    pub public: String,
}

pub fn keygen(dir: &Path, name: &str) -> Key {
    let private = dir.join(name);
    let status = std::process::Command::new("ssh-keygen")
        .args([
            "-q",
            "-t",
            "ed25519",
            "-N",
            "",
            "-C",
            "redis-lens-test",
            "-f",
        ])
        .arg(&private)
        .stdin(std::process::Stdio::null())
        .status()
        .expect("run ssh-keygen");
    assert!(status.success(), "ssh-keygen failed");
    let public = std::fs::read_to_string(private.with_extension("pub"))
        .expect("read the public key")
        .trim()
        .to_string();
    Key { private, public }
}

/// The key type and base64 of a `.pub` line (without its comment).
fn key_part(public: &str) -> String {
    public
        .split_whitespace()
        .take(2)
        .collect::<Vec<_>>()
        .join(" ")
}

pub struct SshBastion {
    /// The published SSH port on 127.0.0.1.
    pub port: u16,
    /// The bastion's ed25519 host key, `ssh-ed25519 AAAA…`, read from the container.
    pub host_key: String,
    pub network: String,
    container: ContainerAsync<GenericImage>,
}

impl SshBastion {
    /// Start a bastion on `network` that lets `authorized` log in as [`SSH_USER`].
    pub async fn start(network: &str, authorized: &Key) -> Self {
        let container = GenericImage::new(SSHD_IMAGE.0, SSHD_IMAGE.1)
            .with_exposed_port(SSH_PORT.tcp())
            .with_wait_for(WaitFor::message_on_stdout("[ls.io-init] done."))
            .with_network(network)
            .with_env_var("USER_NAME", SSH_USER)
            .with_env_var("PUBLIC_KEY", authorized.public.clone())
            .with_env_var("PASSWORD_ACCESS", "false")
            .with_copy_to(
                CopyTargetOptions::new("/config/sshd/sshd_config.d/redis-lens.conf")
                    .with_mode(0o644),
                b"AllowTcpForwarding yes\n".to_vec(),
            )
            .with_startup_timeout(Duration::from_secs(120))
            .start()
            .await
            .expect("start the sshd container (is Docker running?)");
        let port = container
            .get_host_port_ipv4(SSH_PORT.tcp())
            .await
            .expect("mapped ssh port");
        wait_for_banner(port).await;
        let mut exec = container
            .exec(
                ExecCommand::new(["cat", HOST_KEY])
                    .with_cmd_ready_condition(CmdWaitFor::exit_code(0)),
            )
            .await
            .expect("read the host key");
        let out = exec.stdout_to_vec().await.expect("host key output");
        let host_key = key_part(&String::from_utf8(out).expect("UTF-8 host key"));
        assert!(host_key.starts_with("ssh-ed25519 "), "{host_key}");
        Self {
            port,
            host_key,
            network: network.to_string(),
            container,
        }
    }

    /// The container's ID, to start servers in its network namespace.
    pub fn id(&self) -> &str {
        self.container.id()
    }

    /// Write a known_hosts file in `dir` holding the bastion's real host key.
    pub fn known_hosts(&self, dir: &Path) -> PathBuf {
        self.known_hosts_with(dir, "known_hosts", &self.host_key)
    }

    /// Write a known_hosts file in `dir` that lists `key` for the bastion.
    pub fn known_hosts_with(&self, dir: &Path, name: &str, key: &str) -> PathBuf {
        let path = dir.join(name);
        std::fs::write(
            &path,
            format!("[127.0.0.1]:{} {}\n", self.port, key_part(key)),
        )
        .expect("write known_hosts");
        path
    }

    /// The tunnel for a profile: this bastion, with `key` and `known_hosts`.
    pub fn tunnel(&self, key: &Key, known_hosts: &Path) -> SshTunnel {
        SshTunnel {
            host: "127.0.0.1".into(),
            port: Some(self.port),
            identity_file: Some(key.private.clone()),
            known_hosts_file: Some(known_hosts.to_path_buf()),
        }
    }
}

/// Wait until sshd sends its banner on the published port (s6 starts it after init).
async fn wait_for_banner(port: u16) {
    use tokio::io::AsyncReadExt;
    let deadline = Instant::now() + Duration::from_secs(60);
    loop {
        if let Ok(Ok(mut s)) = tokio::time::timeout(
            Duration::from_secs(2),
            tokio::net::TcpStream::connect(("127.0.0.1", port)),
        )
        .await
        {
            let mut buf = [0u8; 8];
            if let Ok(Ok(n)) =
                tokio::time::timeout(Duration::from_secs(2), s.read_exact(&mut buf)).await
                && n == 8
                && buf.starts_with(b"SSH-2.0")
            {
                return;
            }
        }
        assert!(Instant::now() < deadline, "sshd did not start");
        tokio::time::sleep(Duration::from_millis(200)).await;
    }
}

/// Where a [`HiddenServer`] runs.
pub enum Place<'a> {
    /// On the network under this container name, which only resolves inside it.
    Network(&'a str, &'a str),
    /// In the bastion's own network namespace, so on its 127.0.0.1.
    OnBastion(&'a SshBastion),
}

/// A Redis or Valkey server that is not published to the host.
pub struct HiddenServer {
    /// Its container name on the network, or `127.0.0.1` on the bastion.
    pub host: String,
    pub port: u16,
    valkey: bool,
    container: ContainerAsync<GenericImage>,
}

impl HiddenServer {
    pub async fn start(place: Place<'_>, valkey: bool, port: u16, args: &[&str]) -> Self {
        Self::start_with(place, valkey, port, args, &[]).await
    }

    /// A server that serves only TLS on 6379, with `tls`'s certificate (the same
    /// settings as `common::tls_server`).
    pub async fn start_tls(place: Place<'_>, valkey: bool, tls: &super::ServerTls) -> Self {
        Self::start_with(place, valkey, 6379, &super::TLS_ARGS, &tls.files()).await
    }

    /// [`Self::start`] with `files` (container path, contents) copied in first.
    pub async fn start_with(
        place: Place<'_>,
        valkey: bool,
        port: u16,
        args: &[&str],
        files: &[(&str, &[u8])],
    ) -> Self {
        let ((image, tag), bin) = if valkey {
            (super::valkey_image(), "valkey-server")
        } else {
            (super::redis_image(), "redis-server")
        };
        let mut cmd = vec![bin.to_string(), "--port".into(), port.to_string()];
        cmd.extend(args.iter().map(|a| a.to_string()));
        let mut req = GenericImage::new(image, tag)
            .with_wait_for(WaitFor::message_on_stdout("Ready to accept connections"))
            .with_cmd(cmd);
        for (path, data) in files {
            req = req.with_copy_to(
                CopyTargetOptions::new(*path).with_mode(0o644),
                data.to_vec(),
            );
        }
        let (req, host) = match place {
            Place::Network(network, name) => (
                req.with_network(network).with_container_name(name),
                name.to_string(),
            ),
            Place::OnBastion(b) => (
                req.with_network(format!("container:{}", b.id())),
                "127.0.0.1".to_string(),
            ),
        };
        // Nothing published: the image's EXPOSE stays inside Docker.
        let container = req
            .with_host_config_modifier(|hc| {
                hc.publish_all_ports = Some(false);
                hc.port_bindings = None;
            })
            .start()
            .await
            .expect("start the server container");
        Self {
            host,
            port,
            valkey,
            container,
        }
    }

    pub fn endpoint(&self) -> Endpoint {
        Endpoint {
            host: self.host.clone(),
            port: self.port,
            tls: false,
        }
    }

    /// Its address on the network, as a primary would see it.
    pub async fn ip(&self) -> String {
        self.container
            .get_bridge_ip_address()
            .await
            .expect("network ip")
            .to_string()
    }

    /// Run `sh -c <script>` in the container and return its standard output. `$CLI` in
    /// the script is the server's CLI with `-p <port>`.
    pub async fn sh(&self, script: &str) -> String {
        let cli = if self.valkey {
            "valkey-cli"
        } else {
            "redis-cli"
        };
        let script = format!("CLI='{cli} --no-auth-warning -p {}'; {script}", self.port);
        let mut exec = self
            .container
            .exec(
                ExecCommand::new(["sh", "-c", &script])
                    .with_cmd_ready_condition(CmdWaitFor::exit_code(0)),
            )
            .await
            .expect("run a command in the server container");
        String::from_utf8(exec.stdout_to_vec().await.expect("output")).expect("UTF-8")
    }
}

/// How many ssh processes on this machine have `-p <port>` in their arguments: the
/// forwards to the bastion published on `port`.
pub fn ssh_processes(port: u16) -> usize {
    let out = std::process::Command::new("ps")
        .args(["-A", "-o", "args="])
        .output()
        .expect("run ps");
    let needle = format!(" -p {port} ");
    String::from_utf8_lossy(&out.stdout)
        .lines()
        .filter(|l| {
            let l = l.trim_start();
            (l.starts_with("ssh ") || l.contains("/ssh ")) && l.contains(&needle)
        })
        .count()
}

/// Wait up to 5 s for [`ssh_processes`] to reach `n`, and return the last count.
pub async fn wait_for_ssh_processes(port: u16, n: usize) -> usize {
    let deadline = Instant::now() + Duration::from_secs(5);
    loop {
        let got = ssh_processes(port);
        if got == n || Instant::now() >= deadline {
            return got;
        }
        tokio::time::sleep(Duration::from_millis(100)).await;
    }
}
